ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = file->f_mapping->host->mm;
    char *tmp_page = NULL;
    ssize_t total_read = 0;
    loff_t pos = *ppos;
    int ret = 0;

    if (!mm || !mm->env_size) {
        return -EINVAL;
    }

    tmp_page = (char *)__get_free_page(GFP_KERNEL);
    if (!tmp_page) {
        return -ENOMEM;
    }

    down_read(&mm->mmap_lock);

    while (pos < mm->env_size && total_read < count) {
        size_t bytes_to_read = min(count - total_read, (size_t)PAGE_SIZE);
        size_t bytes_read = 0;

        if (access_process_vm(current, (unsigned long)(mm->env + pos), tmp_page, bytes_to_read, FOLL_FORCE)) {
            bytes_read = copy_to_user(buf + total_read, tmp_page, bytes_to_read) ? 0 : bytes_to_read;
            total_read += bytes_read;
            pos += bytes_read;
        } else {
            ret = -EFAULT;
            break;
        }
    }

    up_read(&mm->mmap_lock);

    free_page((unsigned long)tmp_page);

    if (ret < 0) {
        return ret;
    }

    *ppos = pos;
    return total_read ? total_read : -EFAULT;
}
